<?php
require_once __DIR__.'/../insights/common.php';
$uid=$fi_user_id;$error='';$ready=fw_has_table($conn,'fw_challenge_goals');
if($ready&&$_SERVER['REQUEST_METHOD']==='POST')try{
 if(!fi_post_csrf())throw new InvalidArgumentException('Refresh and try again.');
 $id=fw_positive_id($_POST['challenge_id']??null);$goal=fw_positive_id($_POST['goal_id']??null);$behavior=fw_text($_POST['behavior']??null);
 if($behavior===''||fw_text_length($behavior)>160)throw new InvalidArgumentException('Describe the saving routine in up to 160 characters.');
 mysqli_begin_transaction($conn);fw_query($conn,'SELECT user_id FROM users WHERE user_id=? FOR UPDATE','i',[$uid]);
 $c=fw_query($conn,'SELECT * FROM savings_challenges WHERE challenge_id=? AND user_id=?','ii',[$id,$uid])[0]??null;
 if(!$c||!fw_query($conn,'SELECT goal_id FROM savings_goals WHERE goal_id=? AND user_id=?','ii',[$goal,$uid]))throw new InvalidArgumentException('Choose your own challenge and savings goal.');
 if(fw_query($conn,'SELECT l.challenge_id FROM fw_challenge_goals l JOIN savings_challenges c ON c.challenge_id=l.challenge_id AND c.user_id=l.user_id WHERE l.user_id=? AND l.goal_id=? AND c.challenge_id<>? AND c.start_date<=? AND c.end_date>=?','iiiss',[$uid,$goal,$id,$c['end_date'],$c['start_date']]))throw new InvalidArgumentException('That goal already supports an overlapping challenge. Choose another goal or dates.');
 if(!fi_checked($_POST['reviewed']??null))throw new InvalidArgumentException('Confirm that progress will use existing goal contributions.');
 fw_query($conn,'INSERT INTO fw_challenge_goals(challenge_id,user_id,goal_id,behavior) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE goal_id=VALUES(goal_id),behavior=VALUES(behavior)','iiis',[$id,$uid,$goal,$behavior]);
 fw_revision($conn,$uid,'savings_challenge',$id,'linked_to_goal',$c,['goal_id'=>$goal,'behavior'=>$behavior]);mysqli_commit($conn);header('Location: challenges.php');exit;
}catch(Throwable $e){mysqli_rollback($conn);$error=$e instanceof InvalidArgumentException?$e->getMessage():'Unable to link the challenge.';}
$challenges=fw_query($conn,'SELECT * FROM savings_challenges WHERE user_id=? ORDER BY start_date DESC','i',[$uid]);$goals=fw_query($conn,'SELECT * FROM savings_goals WHERE user_id=? ORDER BY goal_name','i',[$uid]);
$links=$ready?fw_query($conn,'SELECT l.*,g.goal_name,c.challenge_name FROM fw_challenge_goals l JOIN savings_goals g ON g.goal_id=l.goal_id AND g.user_id=l.user_id JOIN savings_challenges c ON c.challenge_id=l.challenge_id AND c.user_id=l.user_id WHERE l.user_id=?','i',[$uid]):[];
