<form method="post"><input type="hidden" name="fw_request_token" value="<?= fi_h(fw_request_token()) ?>"><input type="hidden" name="csrf_token" value="<?= fi_h($_SESSION['csrf_token']) ?>"><div class="fi-form-grid"><label >Challenge<select class="form-select" name="challenge_id" required><option value="">Select challenge</option><?php foreach($challenges as $c):?><option value="<?= (int)$c['challenge_id'] ?>"><?= fi_h($c['challenge_name'].' · '.$c['start_date'].' to '.$c['end_date']) ?></option><?php endforeach;?></select></label><label class="col-md-6">Savings goal<select class="form-select" name="goal_id" required><option value="">Select goal</option><?php foreach($goals as $g):?><option value="<?= (int)$g['goal_id'] ?>"><?= fi_h($g['goal_name']) ?></option><?php endforeach;?></select></label><label class="fi-full">Your routine<input class="form-control" name="behavior" maxlength="160" placeholder="Set aside 100 after each paid shift" required></label></div><label class="fi-check"><input type="checkbox" name="reviewed" value="1" required><span>Use goal contributions as this challenge’s progress, replacing its manual total.</span></label><button class="btn btn-primary">Link routine to goal</button></form>
